import { Navbar } from "@/components/layout/Navbar";
import { Footer } from "@/components/layout/Footer";
import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Skeleton } from "@/components/ui/skeleton";
import { CalendarIcon, Lock, CreditCard, X, Check, Plus } from "lucide-react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { useMemo, useState, useEffect } from "react";
import { format, addDays, startOfDay, isValid, parseISO } from "date-fns";
import { cn } from "@/lib/utils";
import { useCourts } from "@/hooks/useCourts";
import { useBookedSlotsAllCourts } from "@/hooks/useBookings";
import { useAuth } from "@/hooks/useAuth";
import { useToast } from "@/hooks/use-toast";
import { useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { PageHeading } from "@/components/layout/PageHeading";
import venueImage from "@/assets/venue/courts.jpg";
import { openPlayStart, venueDate } from "@/lib/openPlay";
import { useNow } from "@/hooks/useNow";

const TIME_SLOTS = [
  { label: "7AM–8AM", start: "07:00:00", display: "7:00 AM" },
  { label: "8AM–9AM", start: "08:00:00", display: "8:00 AM" },
  { label: "9AM–10AM", start: "09:00:00", display: "9:00 AM" },
  { label: "10AM–11AM", start: "10:00:00", display: "10:00 AM" },
  { label: "11AM–12PM", start: "11:00:00", display: "11:00 AM" },
  { label: "12PM–1PM", start: "12:00:00", display: "12:00 PM" },
  { label: "1PM–2PM", start: "13:00:00", display: "1:00 PM" },
  { label: "2PM–3PM", start: "14:00:00", display: "2:00 PM" },
  { label: "3PM–4PM", start: "15:00:00", display: "3:00 PM" },
  { label: "4PM–5PM", start: "16:00:00", display: "4:00 PM" },
  { label: "5PM–6PM", start: "17:00:00", display: "5:00 PM" },
  { label: "6PM–7PM", start: "18:00:00", display: "6:00 PM" },
  { label: "7PM–8PM", start: "19:00:00", display: "7:00 PM" },
  { label: "8PM–9PM", start: "20:00:00", display: "8:00 PM" },
  { label: "9PM–10PM", start: "21:00:00", display: "9:00 PM" },
  { label: "10PM–11PM", start: "22:00:00", display: "10:00 PM" },
];

// slotKey = `${courtId}::${slotStart}`
const makeKey = (courtId: string, slotStart: string) => `${courtId}::${slotStart}`;

const Courts = () => {
  const { data: courts, isLoading, error: courtsError, refetch: refetchCourts } = useCourts();
  const now = useNow();
  const { user } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const [searchParams] = useSearchParams();
  const [selectedDate, setSelectedDate] = useState<Date>(() => {
    const requested = searchParams.get("date");
    const today = parseISO(venueDate());
    const date = requested && /^\d{4}-\d{2}-\d{2}$/.test(requested) ? parseISO(requested) : today;
    return isValid(date) && date >= today && date <= addDays(today, 60) ? startOfDay(date) : today;
  });
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [datePickerOpen, setDatePickerOpen] = useState(false);
  const [dragging, setDragging] = useState<null | { mode: "add" | "remove" }>(null);

  const dateStr = format(selectedDate, "yyyy-MM-dd");
  const { data: bookedRows, error: slotsError, isLoading: slotsLoading, refetch: refetchSlots } = useBookedSlotsAllCourts(dateStr);
  const availabilityUnavailable = !!courtsError || !!slotsError || slotsLoading;
  const isPast = (start_time: string) => openPlayStart({ session_date: dateStr, start_time }) <= now;

  // Reset selection when date changes
  useEffect(() => {
    setSelected(new Set());
  }, [dateStr]);

  useEffect(() => {
    setSelected((previous) => {
      const future = new Set([...previous].filter((key) => openPlayStart({ session_date: dateStr, start_time: key.split("::")[1] }) > now));
      return future.size === previous.size ? previous : future;
    });
  }, [dateStr, now]);

  // Live availability: subscribe to booking_slots changes for the current date
  // (booking_slots is visible to all authenticated users; bookings is not).
  useEffect(() => {
    const channel = supabase
      .channel(`booking-slots-${dateStr}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "booking_slots",
          filter: `booking_date=eq.${dateStr}`,
        },
        (payload) => {
          queryClient.invalidateQueries({ queryKey: ["booked-slots-all", dateStr] });

          const row = payload.eventType === "DELETE" ? payload.old : payload.new;
          if (!row) return;
          // Only react when a slot became reserved (or was deleted)
          const nowReserved = payload.eventType !== "DELETE" && row.is_reserved === true;
          if (!nowReserved && payload.eventType !== "DELETE") return;

          setSelected((prev) => {
            const next = new Set(prev);
            let removed = 0;
            prev.forEach((k) => {
              const [courtId, slotStart] = k.split("::");
              if (courtId === row.court_id && slotStart === row.start_time) {
                next.delete(k);
                removed++;
              }
            });
            if (removed > 0) {
              toast({
                title: "A slot you selected was just booked",
                description: `${removed} slot${removed > 1 ? "s were" : " was"} removed from your selection.`,
                variant: "destructive",
              });
            }
            return next;
          });
        }
      )
      .on(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "bookings",
          filter: `booking_date=eq.${dateStr}`,
        },
        () => {
          queryClient.invalidateQueries({ queryKey: ["booked-slots-all", dateStr] });
        }
      )
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "open_play_sessions" },
        () => void queryClient.invalidateQueries({ queryKey: ["booked-slots-all", dateStr] }),
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [dateStr, queryClient, toast]);


  // Map of courtId -> [(start, end, status)] for booked ranges
  const bookedByCourt = useMemo(() => {
    const map = new Map<string, Map<string, { status: "pending" | "paid"; isAdmin: boolean; note: string | null }>>();
    (bookedRows || []).forEach((b) => {
      if (!map.has(b.court_id)) map.set(b.court_id, new Map());
      map.get(b.court_id)!.set(b.start_time, { status: b.status, isAdmin: b.is_admin_block, note: b.admin_note });
    });
    return map;
  }, [bookedRows]);

  useEffect(() => {
    if (!bookedRows) return;
    const reserved = new Set(bookedRows.map((row) => makeKey(row.court_id, row.start_time)));
    setSelected((previous) => {
      const available = new Set([...previous].filter((key) => !reserved.has(key)));
      return available.size === previous.size ? previous : available;
    });
  }, [bookedRows]);

  const getBookedStatus = (courtId: string, slotStart: string) =>
    bookedByCourt.get(courtId)?.get(slotStart) ?? null;

  const isBooked = (courtId: string, slotStart: string) => getBookedStatus(courtId, slotStart) !== null;

  // End drag on pointer release anywhere
  useEffect(() => {
    const stop = () => setDragging(null);
    window.addEventListener("pointerup", stop);
    window.addEventListener("pointercancel", stop);
    return () => {
      window.removeEventListener("pointerup", stop);
      window.removeEventListener("pointercancel", stop);
    };
  }, []);

  const toggleCell = (key: string, mode: "add" | "remove") => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (mode === "add") next.add(key);
      else next.delete(key);
      return next;
    });
  };

  const handlePointerDown = (courtId: string, slotStart: string, e: React.PointerEvent) => {
    if (e.button > 0 || availabilityUnavailable || isPast(slotStart) || isBooked(courtId, slotStart)) return;
    const key = makeKey(courtId, slotStart);
    const mode: "add" | "remove" = selected.has(key) ? "remove" : "add";
    setDragging({ mode });
    toggleCell(key, mode);
    // capture so pointerenter still fires on siblings
    (e.currentTarget as HTMLElement).releasePointerCapture?.(e.pointerId);
  };

  const handlePointerEnter = (courtId: string, slotStart: string) => {
    if (!dragging) return;
    if (availabilityUnavailable || isPast(slotStart) || isBooked(courtId, slotStart)) return;
    toggleCell(makeKey(courtId, slotStart), dragging.mode);
  };

  // Build selections grouped by court for summary + checkout
  const selections = useMemo(() => {
    if (!courts) return [];
    const byCourt = new Map<string, string[]>();
    selected.forEach((k) => {
      const [courtId, slotStart] = k.split("::");
      if (!byCourt.has(courtId)) byCourt.set(courtId, []);
      byCourt.get(courtId)!.push(slotStart);
    });
    return Array.from(byCourt.entries())
      .map(([courtId, slots]) => {
        const court = courts.find((c) => c.id === courtId);
        if (!court) return null;
        return {
          courtId,
          courtName: court.name,
          pricePerHour: Number(court.price_per_hour),
          slots: slots.sort(),
        };
      })
      .filter(Boolean) as Array<{ courtId: string; courtName: string; pricePerHour: number; slots: string[] }>;
  }, [selected, courts]);

  const totalHours = selections.reduce((s, sel) => s + sel.slots.length, 0);
  const totalPrice = selections.reduce((s, sel) => s + sel.slots.length * sel.pricePerHour, 0);

  const handleProceed = () => {
    if (availabilityUnavailable) return;
    if (!user) {
      toast({ title: "Please sign in", description: "You need an account to book courts." });
      navigate("/auth", { state: { from: "/courts?date=" + dateStr } });
      return;
    }
    if (selections.length === 0) return;
    navigate("/checkout", {
      state: {
        date: dateStr,
        selections,
        totalPrice,
      },
    });
  };

  return (
    <div className="min-h-screen bg-background">
      <Navbar />

      <main id="main-content" className="pt-32 pb-32 md:pt-40">
        <div className="site-container">
          <PageHeading title="Book a court" description="Make a little time for a game. Pick a date, then select the hours and courts that work for your group."
            image={venueImage} imageAlt="The Pickle Box indoor courts" />

          {/* Date picker + legend */}
          <div className="mb-5 flex flex-col gap-4 rounded-xl border border-border bg-card p-4 sm:flex-row sm:items-center md:p-5">
            <Popover open={datePickerOpen} onOpenChange={setDatePickerOpen}>
              <PopoverTrigger asChild>
                <Button variant="outline" className="w-full sm:w-auto justify-start" aria-label="Choose booking date">
                  <CalendarIcon className="h-4 w-4 mr-2" />
                  {format(selectedDate, "EEEE, MMM d, yyyy")}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0" align="start">
                <Calendar
                  mode="single"
                  selected={selectedDate}
                  onSelect={(d) => { if (d) { setSelectedDate(startOfDay(d)); setDatePickerOpen(false); } }}
                  disabled={(d) => d < parseISO(venueDate()) || d > addDays(parseISO(venueDate()), 60)}
                  initialFocus
                  className={cn("p-3 pointer-events-auto")}
                />
              </PopoverContent>
            </Popover>

            <div className="flex flex-wrap items-center gap-3 text-xs text-muted-foreground sm:ml-auto">
              <div className="flex items-center gap-1.5">
                <span className="inline-block h-3 w-3 rounded border border-border bg-background" />
                Available
              </div>
              <div className="flex items-center gap-1.5">
                <span className="inline-block h-3 w-3 rounded bg-primary" />
                Selected
              </div>
              <div className="flex items-center gap-1.5">
                <span className="inline-block h-3 w-3 rounded bg-muted" />
                Reserved (pending)
              </div>
              <div className="flex items-center gap-1.5">
                <span className="inline-block h-3 w-3 rounded bg-destructive/30" />
                Booked (paid)
              </div>
            </div>
          </div>
          <p className="mb-4 text-xs leading-5 text-muted-foreground">Select each hour you want to reserve. You can drag across neighboring hours, too. All times are Philippine time.</p>

          {/* Grid */}
          {courtsError || slotsError ? (
            <div role="alert" className="rounded-xl border border-destructive/30 p-6">
              <p>Could not load court availability. Please try again before selecting a time.</p>
              <Button variant="outline" className="mt-3" onClick={() => { void refetchCourts(); void refetchSlots(); }}>Try again</Button>
            </div>
          ) : isLoading || slotsLoading ? (
            <Skeleton className="h-[600px] w-full rounded-xl" />
          ) : !courts?.length ? (
            <p className="rounded-xl border border-border p-6">No courts are available for online booking right now. Please check back later.</p>
          ) : (
            <div key={dateStr} className="booking-grid-enter overflow-x-auto rounded-xl border border-border bg-card select-none">
            <div style={{ minWidth: Math.max(340, 88 + courts.length * 116) }}>
              {/* Header row */}
              <div
                className="grid bg-muted/50 border-b border-border text-xs font-semibold text-muted-foreground"
                style={{ gridTemplateColumns: `88px repeat(${courts.length}, minmax(0, 1fr))` }}
              >
                <div className="p-3">Time</div>
                {courts.map((court) => (
                  <div key={court.id} className="p-3 border-l border-border">
                    <div className="text-foreground text-sm normal-case tracking-normal">{court.name}</div>
                    <div className="mt-1 text-xs font-normal text-muted-foreground normal-case tracking-normal">
                      ₱{court.price_per_hour}/hr
                    </div>
                  </div>
                ))}
              </div>

              {/* Rows */}
              {TIME_SLOTS.map((slot) => (
                <div
                  key={slot.start}
                  className="grid border-b border-border last:border-b-0"
                  style={{ gridTemplateColumns: `88px repeat(${courts.length}, minmax(0, 1fr))` }}
                >
                  <div className="p-3 text-xs font-medium text-muted-foreground flex items-center bg-muted/20">
                    {slot.label}
                  </div>
                  {courts.map((court) => {
                    const info = getBookedStatus(court.id, slot.start);
                    const booked = info !== null;
                    const isAdminBlock = info?.isAdmin === true;
                    const isPaid = info?.status === "paid";
                    const key = makeKey(court.id, slot.start);
                    const isSelected = selected.has(key);
                    const past = isPast(slot.start);
                    return (
                      <button
                        key={court.id}
                        type="button"
                        disabled={booked || past || availabilityUnavailable}
                        aria-label={`${court.name}, ${slot.label}${booked ? ", reserved" : past ? ", past" : ""}`}
                        aria-pressed={booked ? undefined : isSelected}
                        onClick={(event) => {
                          if (event.detail === 0 && !booked && !past && !availabilityUnavailable) toggleCell(key, isSelected ? "remove" : "add");
                        }}
                        onPointerDown={(e) => handlePointerDown(court.id, slot.start, e)}
                        onPointerEnter={() => handlePointerEnter(court.id, slot.start)}
                        className={cn(
                          "booking-cell group border-l border-border h-14 md:h-16 transition-colors text-xs font-medium touch-none",
                          booked && isAdminBlock && "bg-accent/50 cursor-not-allowed text-foreground",
                          booked && !isAdminBlock && !isPaid && "bg-muted/60 cursor-not-allowed text-muted-foreground",
                          booked && !isAdminBlock && isPaid && "bg-destructive/15 cursor-not-allowed text-destructive",
                          past && !booked && "bg-muted/40 text-muted-foreground cursor-not-allowed",
                          !booked && !past && !isSelected && "bg-background hover:bg-primary/10 cursor-pointer",
                          !booked && isSelected && "bg-primary text-primary-foreground shadow-inner"
                        )}
                      >
                        {booked ? (
                          <span className="inline-flex items-center gap-1">
                            <Lock className="h-3 w-3" />
                            {isAdminBlock ? info.note === "Open Play" ? "Open Play" : "Admin Reserved" : isPaid ? "Booked" : "Reserved"}
                          </span>
                        ) : past ? <span>Past</span> : isSelected ? (
                          <span className="slot-check" aria-hidden="true"><Check className="h-4 w-4" /></span>
                        ) : <Plus aria-hidden="true" className="mx-auto h-4 w-4 text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100 group-focus-visible:opacity-100" />}
                      </button>
                    );
                  })}
                </div>
              ))}
            </div>
            </div>
          )}
        </div>
      </main>

      {/* Sticky checkout bar */}
      {selections.length > 0 && (
        <div className="booking-summary fixed bottom-0 left-0 right-0 z-40 border-t border-border bg-card shadow-lg">
          <div className="container mx-auto px-4 py-3 flex flex-col sm:flex-row sm:items-center gap-3">
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 flex-wrap" aria-live="polite" aria-atomic="true">
                <span className="text-sm font-semibold text-foreground">
                  {totalHours} {totalHours === 1 ? "slot" : "slots"} · {selections.length} {selections.length === 1 ? "court" : "courts"}
                </span>
                <span key={totalHours} className="booking-total text-lg font-bold tabular-nums text-primary">₱{totalPrice}</span>
              </div>
              <div className="text-xs text-muted-foreground mt-0.5 truncate">
                {selections.map((s) => `${s.courtName} (${s.slots.length}h)`).join(" · ")}
              </div>
            </div>
            <div className="flex gap-2">
              <Button variant="ghost" size="sm" onClick={() => setSelected(new Set())}>
                <X className="h-4 w-4 mr-1" />
                Clear
              </Button>
              <Button variant="hero" size="lg" onClick={handleProceed} disabled={availabilityUnavailable || selections.some((s) => s.slots.some(isPast))}>
                <CreditCard className="h-4 w-4 mr-2" />
                Proceed to Checkout
              </Button>
            </div>
          </div>
        </div>
      )}

      <Footer />
    </div>
  );
};

export default Courts;

import { useMemo, useState } from "react";
import { Navigate } from "react-router-dom";
import { format, parseISO } from "date-fns";
import { Users, Clock, Calendar, MapPin, Trophy, X, QrCode, CheckCircle2 } from "lucide-react";
import { Navbar } from "@/components/layout/Navbar";
import { Footer } from "@/components/layout/Footer";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useAuth } from "@/hooks/useAuth";
import { useCourts } from "@/hooks/useCourts";
import { useToast } from "@/hooks/use-toast";
import {
  useOpenPlaySessions,
  useOpenPlayRoster,
  useRegisterOpenPlay,
  useCancelOpenPlayRegistration,
} from "@/hooks/useOpenPlay";
import { QRCodeDialog } from "@/components/checkin/QRCodeDialog";
import { openPlayErrorMessage, openPlayStart } from "@/lib/openPlay";
import gcashQr from "@/assets/gcash-qr.png";
import { PageHeading } from "@/components/layout/PageHeading";
import communityImage from "@/assets/venue/community.jpg";
import { useNow } from "@/hooks/useNow";

const skillLabel: Record<string, string> = {
  all: "All Levels",
  "2.5-3.0": "2.5 – 3.0",
  "3.5": "3.5",
  "4.0+": "4.0+",
};

const OpenPlay = () => {
  const now = useNow();
  const { user, loading: authLoading } = useAuth();
  const { data: sessions, isLoading, error, refetch } = useOpenPlaySessions();
  const { data: courts } = useCourts();
  const [selectedSessionId, setSelectedSessionId] = useState<string | null>(null);
  const openSession = sessions?.find((session) => session.id === selectedSessionId);
  const [paymentRef, setPaymentRef] = useState("");
  const [qrOpen, setQrOpen] = useState(false);
  const { toast } = useToast();
  const register = useRegisterOpenPlay();
  const cancel = useCancelOpenPlayRegistration();

  const courtNameMap = useMemo(() => {
    const m = new Map<string, string>();
    courts?.forEach((c) => m.set(c.id, c.name));
    return m;
  }, [courts]);

  const { data: roster, isLoading: rosterLoading, error: rosterError, refetch: refetchRoster } = useOpenPlayRoster(openSession?.id);

  const selectSession = (id: string | null) => {
    setSelectedSessionId(id);
    setPaymentRef("");
    setQrOpen(false);
  };

  if (authLoading) return null;
  if (!user) return <Navigate to="/auth" replace />;

  const scheduled = (sessions ?? []).filter((s) => s.status === "scheduled"
    && (openPlayStart(s) > now || !!s.my_status));
  const started = !!openSession && openPlayStart(openSession) <= now;
  const canCancel = !!openSession && ["registered", "waitlisted"].includes(openSession.my_status)
    && now < openPlayStart(openSession) - openSession.cancel_cutoff_hours * 3_600_000;

  const handleRegister = async () => {
    if (!openSession || started || register.isPending || error) return;
    if (openSession.price_php > 0 && !paymentRef.trim()) {
      toast({
        title: "GCash reference required",
        description: "Enter your GCash reference number to register.",
        variant: "destructive",
      });
      return;
    }
    try {
      const res = await register.mutateAsync({
        sessionId: openSession.id,
        paymentReference: paymentRef.trim() || undefined,
      });
      toast({
        title:
          res.status === "waitlisted"
            ? `Added to waitlist (#${res.waitlist_position})`
            : "You're registered!",
      });
      setPaymentRef("");
      selectSession(null);
    } catch (e: unknown) {
      toast({ title: "Registration failed", description: openPlayErrorMessage(e), variant: "destructive" });
    }
  };

  const handleCancel = async (registrationId: string) => {
    try {
      await cancel.mutateAsync(registrationId);
      toast({ title: "Registration cancelled" });
      selectSession(null);
    } catch (e: unknown) {
      toast({ title: "Cancel failed", description: openPlayErrorMessage(e), variant: "destructive" });
    }
  };

  const myRosterRow = roster?.find((r) => r.user_id === user.id);

  return (
    <div className="min-h-screen bg-background">
      <Navbar />
      <main id="main-content" className="pt-32 pb-20 md:pt-40">
        <div className="site-container">
          <PageHeading title="Open Play" description="A game is a good place to meet. Find a session for your level, register as a player, and join the people on court."
            image={communityImage} imageAlt="Players greeting each other at The Pickle Box">
            <Badge variant="secondary" className="text-sm">
              <Trophy className="h-3 w-3 mr-1" /> {scheduled.filter((s) => openPlayStart(s) > Date.now()).length} upcoming
            </Badge>
            <span className="text-xs text-muted-foreground">Fees and remaining spots are shown on each session.</span>
          </PageHeading>

          {error ? (
            <div role="alert" className="rounded-lg border border-destructive/30 p-6">
              <p>Could not load Open Play sessions. Please try again.</p>
              <Button variant="outline" className="mt-3" onClick={() => void refetch()}>Try again</Button>
            </div>
          ) : isLoading ? (
            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
              {[1, 2, 3].map((i) => (
                <Skeleton key={i} className="h-56 w-full rounded-xl" />
              ))}
            </div>
          ) : scheduled.length === 0 ? (
            <Card>
              <CardContent className="py-16 text-center">
                <Trophy className="h-12 w-12 text-muted-foreground mx-auto mb-4" />
                <p className="text-muted-foreground">
                  No open play sessions scheduled yet. Check back soon!
                </p>
              </CardContent>
            </Card>
          ) : (
            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
              {scheduled.map((s) => {
                const isFull = s.registered_count >= s.max_players;
                const mine = s.my_status;
                return (
                  <Card
                    key={s.id}
                    role="button"
                    tabIndex={0}
                    aria-label={`View ${s.title || "Open Play"} session`}
                    className="cursor-pointer transition-colors hover:border-primary/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    onClick={() => selectSession(s.id)}
                    onKeyDown={(event) => {
                      if (event.key === "Enter" || event.key === " ") {
                        event.preventDefault();
                        selectSession(s.id);
                      }
                    }}
                  >
                    <CardContent className="space-y-5 p-6">
                      <div className="flex items-start justify-between">
                        <div>
                          <h3 className="font-semibold text-lg text-foreground">
                            {s.title || "Open Play"}
                          </h3>
                          <p className="text-sm text-muted-foreground">
                            {skillLabel[s.skill]}
                          </p>
                        </div>
                        {mine === "registered" && <Badge>Registered</Badge>}
                        {mine === "checked_in" && (
                          <Badge className="bg-primary text-primary-foreground">
                            <CheckCircle2 className="h-3 w-3 mr-1" /> Checked in
                          </Badge>
                        )}
                        {mine === "waitlisted" && (
                          <Badge variant="secondary">Waitlist #{s.my_waitlist_position}</Badge>
                        )}
                      </div>

                      <div className="space-y-1.5 text-sm text-muted-foreground">
                        <div className="flex items-center gap-2">
                          <Calendar className="h-4 w-4" />
                          {format(parseISO(s.session_date), "EEE, MMM d")}
                        </div>
                        <div className="flex items-center gap-2">
                          <Clock className="h-4 w-4" />
                          {s.start_time.slice(0, 5)} – {s.end_time.slice(0, 5)}
                        </div>
                        <div className="flex items-center gap-2">
                          <MapPin className="h-4 w-4" />
                          {s.court_ids
                            .map((id) => courtNameMap.get(id) ?? "Court")
                            .join(", ")}
                        </div>
                      </div>

                      <div className="flex items-center justify-between pt-3 border-t border-border">
                        <div className="flex items-center gap-1.5 text-sm">
                          <Users className="h-4 w-4 text-primary" />
                          <span className="font-medium text-foreground">
                            {s.registered_count}/{s.max_players}
                          </span>
                          {s.waitlist_count > 0 && (
                            <span className="text-xs text-muted-foreground">
                              +{s.waitlist_count} waitlist
                            </span>
                          )}
                        </div>
                        <div className="text-right">
                          <p className="text-lg font-bold text-foreground">
                            {s.price_php > 0 ? `₱${s.price_php}` : "Free"}
                          </p>
                          {isFull && !mine && (
                            <p className="text-xs text-destructive">Full</p>
                          )}
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          )}
        </div>
      </main>

      <Dialog open={!!openSession} onOpenChange={(o) => !o && selectSession(null)}>
        <DialogContent className="max-h-[85dvh] overflow-y-auto max-w-lg">
          {openSession && (
            <>
              <DialogHeader>
                <DialogTitle>{openSession.title || "Open Play"}</DialogTitle>
                <DialogDescription>
                  {format(parseISO(openSession.session_date), "EEEE, MMM d")} ·{" "}
                  {openSession.start_time.slice(0, 5)} –{" "}
                  {openSession.end_time.slice(0, 5)} · {skillLabel[openSession.skill]}
                </DialogDescription>
              </DialogHeader>

              <div className="space-y-4">
                <div className="grid grid-cols-2 gap-3 text-sm">
                  <div className="p-3 rounded-lg bg-muted/50">
                    <p className="text-xs text-muted-foreground">Courts</p>
                    <p className="font-medium">
                      {openSession.court_ids
                        .map((id) => courtNameMap.get(id) ?? "Court")
                        .join(", ")}
                    </p>
                  </div>
                  <div className="p-3 rounded-lg bg-muted/50">
                    <p className="text-xs text-muted-foreground">Fee per player</p>
                    <p className="font-medium">
                      {openSession.price_php > 0 ? `₱${openSession.price_php}` : "Free"}
                    </p>
                  </div>
                  <div className="p-3 rounded-lg bg-muted/50">
                    <p className="text-xs text-muted-foreground">Capacity</p>
                    <p className="font-medium">
                      {openSession.registered_count}/{openSession.max_players} registered
                    </p>
                  </div>
                  <div className="p-3 rounded-lg bg-muted/50">
                    <p className="text-xs text-muted-foreground">Waitlist</p>
                    <p className="font-medium">{openSession.waitlist_count}</p>
                  </div>
                </div>

                {openSession.notes && (
                  <p className="text-sm text-muted-foreground">{openSession.notes}</p>
                )}

                <div>
                  <p className="text-sm font-medium mb-2">Your registration</p>
                  <div className="max-h-40 overflow-y-auto space-y-1 pr-1">
                    {rosterLoading ? (
                      <p className="text-sm text-muted-foreground">Loading your registration...</p>
                    ) : rosterError ? (
                      <div role="alert" className="text-sm text-destructive">
                        Could not load your registration.
                        <Button variant="link" onClick={() => void refetchRoster()}>Try again</Button>
                      </div>
                    ) : (roster ?? []).length === 0 && (
                      <p className="text-sm text-muted-foreground">You haven't registered for this session.</p>
                    )}
                    {(roster ?? []).map((r) => (
                      <div
                        key={r.registration_id}
                        className="flex items-center justify-between text-sm py-1"
                      >
                        <span>{r.full_name || "Player"}</span>
                        {r.status === "waitlisted" ? (
                          <Badge variant="secondary" className="text-xs">
                            Waitlist #{r.waitlist_position}
                          </Badge>
                        ) : (
                          <Badge variant="outline" className="text-xs">
                            {r.status === "checked_in" ? "Checked in" : r.status === "no_show" ? "No-show" : "Registered"}
                          </Badge>
                        )}
                      </div>
                    ))}
                  </div>
                </div>

                {!openSession.my_status && openSession.price_php > 0 && (
                  <div className="space-y-2">
                    <img src={gcashQr} alt="Scan this GCash QR code to pay the session fee" className="mx-auto h-40 w-40 rounded-lg object-contain bg-white" />
                    <Label htmlFor="gcash-ref">GCash reference number</Label>
                    <Input
                      id="gcash-ref"
                      placeholder="e.g. 1234567890123"
                      value={paymentRef}
                      maxLength={128}
                      onChange={(e) => setPaymentRef(e.target.value)}
                    />
                    <p className="text-xs text-muted-foreground">
                      Send ₱{openSession.price_php} to our GCash and enter the reference
                      number. Admin will verify before the session.
                    </p>
                  </div>
                )}
              </div>

              <p className="text-xs text-muted-foreground">
                Cancellation closes {openSession.cancel_cutoff_hours} hours before the session starts (Philippine time).
                {started ? " This session has already started." : openSession.my_status && !canCancel ? " Contact the venue for changes to this registration." : ""}
              </p>

              {myRosterRow && (
                <div className="text-sm">
                  {myRosterRow.status === "cancelled" ? (
                    <span className="inline-flex items-center gap-1.5 font-medium text-destructive">
                      <X className="h-3.5 w-3.5" /> Cancelled
                    </span>
                  ) : myRosterRow.checked_in_at ? (
                    <span className="inline-flex items-center gap-1.5 font-medium text-primary">
                      <CheckCircle2 className="h-3.5 w-3.5" />
                      Checked in · {format(parseISO(myRosterRow.checked_in_at), "MMM d, p")}
                    </span>
                  ) : ["registered", "waitlisted"].includes(myRosterRow.status) ? (
                    <span className="inline-flex items-center gap-1.5 text-muted-foreground">
                      <Clock className="h-3.5 w-3.5" /> Not checked in yet
                    </span>
                  ) : null}
                </div>
              )}

              {myRosterRow &&
                (myRosterRow.payment_status === "completed" &&
                ["registered", "checked_in"].includes(myRosterRow.status) ? (
                  <Button variant="outline" className="w-full" onClick={() => setQrOpen(true)}>
                    <QrCode className="h-4 w-4 mr-2" />
                    {myRosterRow.checked_in_at ? "View QR (checked in)" : "Show check-in QR"}
                  </Button>
                ) : (
                  <p className="text-xs text-muted-foreground">
                    {myRosterRow.status === "waitlisted"
                      ? "You'll get a check-in QR code once you move off the waitlist and your payment is approved."
                      : "Your check-in QR code unlocks once the admin approves your payment."}
                  </p>
                ))}

              <DialogFooter>
                {openSession.my_status ? (
                  <Button
                    variant="destructive"
                    onClick={() => myRosterRow && handleCancel(myRosterRow.registration_id)}
                    disabled={cancel.isPending || !myRosterRow || !canCancel || !!rosterError || !!error}
                  >
                    <X className="h-4 w-4 mr-1" />
                    Cancel Registration
                  </Button>
                ) : (
                  <Button onClick={handleRegister} disabled={register.isPending || started || !!error || !!rosterError || rosterLoading}>
                    {openSession.registered_count >= openSession.max_players
                      ? "Join Waitlist"
                      : `Register${openSession.price_php > 0 ? ` — ₱${openSession.price_php}` : ""}`}
                  </Button>
                )}
              </DialogFooter>
            </>
          )}
        </DialogContent>
      </Dialog>

      <QRCodeDialog
        open={qrOpen && !!openSession}
        onOpenChange={setQrOpen}
        kind="open_play"
        id={myRosterRow?.registration_id}
        title={openSession?.title || "Open Play"}
        subtitle={
          openSession
            ? `${format(parseISO(openSession.session_date), "EEE, MMM d")} · ${openSession.start_time} – ${openSession.end_time}`
            : undefined
        }
        referenceCode={myRosterRow?.payment_reference}
        checkedInAt={myRosterRow?.checked_in_at}
      />

      <Footer />
    </div>
  );
};

export default OpenPlay;

import { useMemo, useState } from "react";
import { AdminLayout } from "@/components/admin/AdminLayout";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { format } from "date-fns";
import { Download, FileText } from "lucide-react";
import { useAdminOpenPlaySessions } from "@/hooks/useOpenPlay";
import { useSessionAttendance, useBookingAttendance } from "@/hooks/useAttendance";
import {
  AttendanceRow,
  exportAttendanceCsv,
  exportAttendancePdf,
  fmtTimestamp,
} from "@/lib/attendanceExport";

const statusLabel: Record<string, string> = {
  registered: "Registered (not checked in)",
  waitlisted: "Waitlisted",
  cancelled: "Cancelled",
  checked_in: "Checked in",
  no_show: "No-show",
  pending: "Pending payment",
  paid: "Paid (not checked in)",
  completed: "Completed",
};

const badgeVariant = (status: string): "default" | "secondary" | "destructive" | "outline" => {
  if (status === "checked_in") return "default";
  if (status === "no_show" || status === "cancelled") return "destructive";
  if (status === "waitlisted" || status === "pending") return "outline";
  return "secondary";
};

const AdminAttendance = () => {
  const { data: sessions } = useAdminOpenPlaySessions();
  const [sessionId, setSessionId] = useState<string>();
  const [date, setDate] = useState<string>(format(new Date(), "yyyy-MM-dd"));

  const { data: roster, isLoading: rosterLoading } = useSessionAttendance(sessionId);
  const { data: bookings, isLoading: bookingsLoading } = useBookingAttendance(date);

  const session = sessions?.find((s: any) => s.id === sessionId);

  const sessionRows: AttendanceRow[] = useMemo(
    () =>
      (roster ?? []).map((r) => ({
        name: r.full_name,
        phone: r.phone,
        detail:
          r.status === "waitlisted" && r.waitlist_position
            ? `Waitlist #${r.waitlist_position}`
            : r.payment_reference || "—",
        status: statusLabel[r.status] ?? r.status,
        payment: r.payment_status,
        registeredAt: fmtTimestamp(r.registered_at),
        checkedInAt: fmtTimestamp(r.checked_in_at),
      })),
    [roster]
  );

  const bookingRows: AttendanceRow[] = useMemo(
    () =>
      (bookings ?? []).map((b) => ({
        name: b.full_name,
        phone: b.phone,
        detail: `${b.court_name} · ${b.start_time}–${b.end_time} · ${b.reference_code || "—"}`,
        status: b.checked_in_at ? "Checked in" : statusLabel[b.status] ?? b.status,
        payment: b.status === "paid" || b.status === "completed" ? "completed" : b.status,
        registeredAt: fmtTimestamp(b.created_at),
        checkedInAt: fmtTimestamp(b.checked_in_at),
      })),
    [bookings]
  );

  const sessionSummary = useMemo(() => {
    const r = roster ?? [];
    const count = (s: string) => r.filter((x) => x.status === s).length;
    return `Checked in: ${count("checked_in")} · Registered: ${count("registered")} · Waitlisted: ${count(
      "waitlisted"
    )} · No-show: ${count("no_show")} · Cancelled: ${count("cancelled")} · Total: ${r.length}`;
  }, [roster]);

  const bookingSummary = useMemo(() => {
    const b = bookings ?? [];
    const checked = b.filter((x) => x.checked_in_at).length;
    const cancelled = b.filter((x) => x.status === "cancelled").length;
    return `Checked in: ${checked} · Not checked in: ${b.length - checked - cancelled} · Cancelled: ${cancelled} · Total: ${b.length}`;
  }, [bookings]);

  const sessionTitle = session
    ? `${session.title || "Open Play"} — ${format(new Date(session.session_date), "MMM d, yyyy")} ${session.start_time}–${session.end_time}`
    : "";

  return (
    <AdminLayout>
      <div className="p-6 lg:p-8">
        <div className="mb-8">
          <h1 className="text-2xl md:text-3xl font-bold text-foreground">Attendance</h1>
          <p className="text-muted-foreground">
            Review and export who checked in, who was waitlisted, and who never showed up
          </p>
        </div>

        <Tabs defaultValue="open-play">
          <TabsList className="mb-6">
            <TabsTrigger value="open-play">Open Play sessions</TabsTrigger>
            <TabsTrigger value="bookings">Court bookings</TabsTrigger>
          </TabsList>

          <TabsContent value="open-play">
            <Card>
              <CardHeader className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
                <div className="w-full md:max-w-md space-y-2">
                  <Label>Session</Label>
                  <Select value={sessionId} onValueChange={setSessionId}>
                    <SelectTrigger>
                      <SelectValue placeholder="Choose a session" />
                    </SelectTrigger>
                    <SelectContent>
                      {(sessions ?? []).map((s: any) => (
                        <SelectItem key={s.id} value={s.id}>
                          {format(new Date(s.session_date), "MMM d")} · {s.start_time}–{s.end_time} ·{" "}
                          {s.title || "Open Play"}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    disabled={!sessionRows.length}
                    onClick={() =>
                      exportAttendanceCsv(
                        `Open Play attendance — ${sessionTitle}`,
                        sessionSummary,
                        sessionRows,
                        `open-play-attendance-${session?.session_date}.csv`
                      )
                    }
                  >
                    <Download className="h-4 w-4 mr-2" /> CSV
                  </Button>
                  <Button
                    disabled={!sessionRows.length}
                    onClick={() =>
                      exportAttendancePdf(
                        "Open Play attendance",
                        sessionTitle,
                        sessionSummary,
                        sessionRows,
                        `open-play-attendance-${session?.session_date}.pdf`
                      )
                    }
                  >
                    <FileText className="h-4 w-4 mr-2" /> PDF
                  </Button>
                </div>
              </CardHeader>
              <CardContent className="p-0">
                {!sessionId ? (
                  <div className="p-8 text-center text-muted-foreground">Select a session to view attendance</div>
                ) : rosterLoading ? (
                  <div className="p-8 text-center text-muted-foreground">Loading attendance...</div>
                ) : !roster?.length ? (
                  <div className="p-8 text-center text-muted-foreground">No registrations for this session</div>
                ) : (
                  <>
                    <p className="px-6 pb-4 text-sm text-muted-foreground">{sessionSummary}</p>
                    <div className="overflow-x-auto">
                      <Table>
                        <TableHeader>
                          <TableRow>
                            <TableHead>Player</TableHead>
                            <TableHead>Status</TableHead>
                            <TableHead>Waitlist / Ref</TableHead>
                            <TableHead>Payment</TableHead>
                            <TableHead>Registered at</TableHead>
                            <TableHead>Checked in at</TableHead>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {roster.map((r) => (
                            <TableRow key={r.id}>
                              <TableCell className="text-foreground">
                                <span className="font-medium">{r.full_name}</span>
                                <span className="block text-xs text-muted-foreground">{r.phone}</span>
                              </TableCell>
                              <TableCell>
                                <Badge variant={badgeVariant(r.status)}>
                                  {statusLabel[r.status] ?? r.status}
                                </Badge>
                              </TableCell>
                              <TableCell className="text-muted-foreground">
                                {r.status === "waitlisted" && r.waitlist_position
                                  ? `#${r.waitlist_position}`
                                  : r.payment_reference || "—"}
                              </TableCell>
                              <TableCell className="text-muted-foreground">{r.payment_status}</TableCell>
                              <TableCell className="text-muted-foreground">
                                {fmtTimestamp(r.registered_at)}
                              </TableCell>
                              <TableCell className="text-muted-foreground">
                                {fmtTimestamp(r.checked_in_at)}
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </div>
                  </>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="bookings">
            <Card>
              <CardHeader className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
                <div className="w-full md:max-w-xs space-y-2">
                  <Label htmlFor="attendance-date">Booking date</Label>
                  <Input
                    id="attendance-date"
                    type="date"
                    value={date}
                    onChange={(e) => setDate(e.target.value)}
                  />
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    disabled={!bookingRows.length}
                    onClick={() =>
                      exportAttendanceCsv(
                        `Court booking attendance — ${format(new Date(date), "MMM d, yyyy")}`,
                        bookingSummary,
                        bookingRows,
                        `booking-attendance-${date}.csv`
                      )
                    }
                  >
                    <Download className="h-4 w-4 mr-2" /> CSV
                  </Button>
                  <Button
                    disabled={!bookingRows.length}
                    onClick={() =>
                      exportAttendancePdf(
                        "Court booking attendance",
                        format(new Date(date), "MMMM d, yyyy"),
                        bookingSummary,
                        bookingRows,
                        `booking-attendance-${date}.pdf`
                      )
                    }
                  >
                    <FileText className="h-4 w-4 mr-2" /> PDF
                  </Button>
                </div>
              </CardHeader>
              <CardContent className="p-0">
                {bookingsLoading ? (
                  <div className="p-8 text-center text-muted-foreground">Loading attendance...</div>
                ) : !bookings?.length ? (
                  <div className="p-8 text-center text-muted-foreground">No bookings on this date</div>
                ) : (
                  <>
                    <p className="px-6 pb-4 text-sm text-muted-foreground">{bookingSummary}</p>
                    <div className="overflow-x-auto">
                      <Table>
                        <TableHeader>
                          <TableRow>
                            <TableHead>Player</TableHead>
                            <TableHead>Court</TableHead>
                            <TableHead>Time</TableHead>
                            <TableHead>Reference</TableHead>
                            <TableHead>Status</TableHead>
                            <TableHead>Booked at</TableHead>
                            <TableHead>Checked in at</TableHead>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {bookings.map((b) => (
                            <TableRow key={b.id}>
                              <TableCell className="text-foreground">
                                <span className="font-medium">{b.full_name}</span>
                                <span className="block text-xs text-muted-foreground">{b.phone}</span>
                              </TableCell>
                              <TableCell className="text-foreground">{b.court_name}</TableCell>
                              <TableCell className="text-muted-foreground">
                                {b.start_time} - {b.end_time}
                              </TableCell>
                              <TableCell className="font-mono text-sm text-muted-foreground">
                                {b.reference_code || "—"}
                              </TableCell>
                              <TableCell>
                                <Badge variant={b.checked_in_at ? "default" : badgeVariant(b.status)}>
                                  {b.checked_in_at ? "Checked in" : statusLabel[b.status] ?? b.status}
                                </Badge>
                              </TableCell>
                              <TableCell className="text-muted-foreground">
                                {fmtTimestamp(b.created_at)}
                              </TableCell>
                              <TableCell className="text-muted-foreground">
                                {fmtTimestamp(b.checked_in_at)}
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </div>
                  </>
                )}
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </AdminLayout>
  );
};

export default AdminAttendance;

import { AdminLayout } from "@/components/admin/AdminLayout";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useAdminBookings } from "@/hooks/useAdmin";
import { supabase } from "@/integrations/supabase/client";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useToast } from "@/hooks/use-toast";
import { format } from "date-fns";
import { CheckCircle, XCircle } from "lucide-react";

const statusVariant: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
  pending: "outline",
  paid: "default",
  cancelled: "destructive",
  completed: "secondary",
};

const AdminBookings = () => {
  const { data: bookings, isLoading } = useAdminBookings();
  const queryClient = useQueryClient();
  const { toast } = useToast();

  const updateBooking = useMutation({
    mutationFn: async ({ bookingId, status }: { bookingId: string; status: "paid" | "cancelled"; paymentId?: string }) => {
      // Use the SECURITY DEFINER RPC — it atomically updates bookings,
      // booking_slots (frees the slot on cancel), and payments together.
      const { error } = await supabase.rpc("resolve_booking_reservation", {
        p_booking_id: bookingId,
        p_status: status,
      });
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["admin", "bookings"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "payments"] });
      toast({ title: "Booking updated successfully" });
    },
    onError: (error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  return (
    <AdminLayout>
      <div className="p-6 lg:p-8">
        <div className="mb-8">
          <h1 className="text-2xl md:text-3xl font-bold text-foreground">Bookings</h1>
          <p className="text-muted-foreground">Manage bookings and verify GCash payments</p>
        </div>

        <Card>
          <CardContent className="p-0">
            {isLoading ? (
              <div className="p-8 text-center text-muted-foreground">Loading bookings...</div>
            ) : bookings?.length === 0 ? (
              <div className="p-8 text-center text-muted-foreground">No bookings yet</div>
            ) : (
              <div className="overflow-x-auto">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Reference</TableHead>
                      <TableHead>Booked By</TableHead>
                      <TableHead>Court</TableHead>
                      <TableHead>Date</TableHead>
                      <TableHead>Time</TableHead>
                      <TableHead>Amount</TableHead>
                      <TableHead>GCash Ref #</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {bookings?.map((booking: any) => {
                      const payment = booking.payments?.[0];
                      const isPending = booking.status === "pending";
                      
                      return (
                        <TableRow key={booking.id}>
                          <TableCell className="font-mono text-sm text-foreground">
                            {booking.reference_code || "—"}
                          </TableCell>
                          <TableCell className="text-foreground">
                            <div>
                              <span className="font-medium">{booking.profiles?.full_name || "Unknown"}</span>
                              {booking.profiles?.phone && (
                                <span className="block text-xs text-muted-foreground">{booking.profiles.phone}</span>
                              )}
                            </div>
                          </TableCell>
                          <TableCell className="text-foreground">
                            {booking.courts?.name || "Unknown"}
                          </TableCell>
                          <TableCell className="text-foreground">
                            {format(new Date(booking.booking_date), "MMM d, yyyy")}
                          </TableCell>
                          <TableCell className="text-muted-foreground">
                            {booking.start_time} - {booking.end_time}
                          </TableCell>
                          <TableCell className="font-semibold text-foreground">
                            ₱{booking.total_amount}
                          </TableCell>
                          <TableCell className="font-mono text-sm">
                            {payment?.transaction_reference ? (
                              <span className="text-foreground">{payment.transaction_reference}</span>
                            ) : (
                              <span className="text-muted-foreground">—</span>
                            )}
                          </TableCell>
                          <TableCell>
                            <Badge variant={statusVariant[booking.status] || "secondary"}>
                              {booking.status.charAt(0).toUpperCase() + booking.status.slice(1)}
                            </Badge>
                          </TableCell>
                          <TableCell className="text-right">
                            {isPending ? (
                              <div className="flex items-center justify-end gap-2">
                                <Button
                                  size="sm"
                                  variant="default"
                                  onClick={() => updateBooking.mutate({
                                    bookingId: booking.id,
                                    status: "paid",
                                    paymentId: payment?.id,
                                  })}
                                  disabled={updateBooking.isPending}
                                >
                                  <CheckCircle className="h-4 w-4 mr-1" />
                                  Approve
                                </Button>
                                <Button
                                  size="sm"
                                  variant="destructive"
                                  onClick={() => updateBooking.mutate({
                                    bookingId: booking.id,
                                    status: "cancelled",
                                    paymentId: payment?.id,
                                  })}
                                  disabled={updateBooking.isPending}
                                >
                                  <XCircle className="h-4 w-4 mr-1" />
                                  Deny
                                </Button>
                              </div>
                            ) : (
                              <span className="text-sm text-muted-foreground">
                                {booking.status === "paid" ? "Verified" : booking.status === "cancelled" ? "Denied" : "—"}
                              </span>
                            )}
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </AdminLayout>
  );
};

export default AdminBookings;

import { AdminLayout } from "@/components/admin/AdminLayout";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { useAllCourts } from "@/hooks/useCourts";
import { supabase } from "@/integrations/supabase/client";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useToast } from "@/hooks/use-toast";
import { Plus, Pencil } from "lucide-react";
import { useState } from "react";

interface CourtFormData {
  name: string;
  description: string;
  price_per_hour: number;
  image_url: string;
  is_active: boolean;
}

const defaultForm: CourtFormData = {
  name: "",
  description: "",
  price_per_hour: 500,
  image_url: "",
  is_active: true,
};

const AdminCourts = () => {
  const { data: courts, isLoading } = useAllCourts();
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const [open, setOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<CourtFormData>(defaultForm);

  const saveMutation = useMutation({
    mutationFn: async (data: CourtFormData & { id?: string }) => {
      if (data.id) {
        const { error } = await supabase
          .from("courts")
          .update({
            name: data.name,
            description: data.description,
            price_per_hour: data.price_per_hour,
            image_url: data.image_url,
            is_active: data.is_active,
          })
          .eq("id", data.id);
        if (error) throw error;
      } else {
        const { error } = await supabase.from("courts").insert({
          name: data.name,
          description: data.description,
          price_per_hour: data.price_per_hour,
          image_url: data.image_url,
          is_active: data.is_active,
        });
        if (error) throw error;
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["courts"] });
      toast({ title: editingId ? "Court updated" : "Court created" });
      setOpen(false);
      setEditingId(null);
      setForm(defaultForm);
    },
    onError: (error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const handleEdit = (court: any) => {
    setEditingId(court.id);
    setForm({
      name: court.name,
      description: court.description || "",
      price_per_hour: court.price_per_hour,
      image_url: court.image_url || "",
      is_active: court.is_active,
    });
    setOpen(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    saveMutation.mutate({ ...form, id: editingId || undefined });
  };

  return (
    <AdminLayout>
      <div className="p-6 lg:p-8">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h1 className="text-2xl md:text-3xl font-bold text-foreground">Courts</h1>
            <p className="text-muted-foreground">Manage your pickleball courts</p>
          </div>
          <Dialog open={open} onOpenChange={(o) => { setOpen(o); if (!o) { setEditingId(null); setForm(defaultForm); } }}>
            <DialogTrigger asChild>
              <Button>
                <Plus className="h-4 w-4 mr-2" />
                Add Court
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>{editingId ? "Edit Court" : "Add New Court"}</DialogTitle>
              </DialogHeader>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="name">Court Name</Label>
                  <Input id="name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} required />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="description">Description</Label>
                  <Textarea id="description" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="price">Price per Hour (₱)</Label>
                  <Input id="price" type="number" value={form.price_per_hour} onChange={(e) => setForm({ ...form, price_per_hour: Number(e.target.value) })} required />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="image">Image URL</Label>
                  <Input id="image" value={form.image_url} onChange={(e) => setForm({ ...form, image_url: e.target.value })} />
                </div>
                <div className="flex items-center gap-2">
                  <Switch checked={form.is_active} onCheckedChange={(checked) => setForm({ ...form, is_active: checked })} />
                  <Label>Active</Label>
                </div>
                <Button type="submit" className="w-full" disabled={saveMutation.isPending}>
                  {saveMutation.isPending ? "Saving..." : editingId ? "Update Court" : "Create Court"}
                </Button>
              </form>
            </DialogContent>
          </Dialog>
        </div>

        <Card>
          <CardContent className="p-0">
            {isLoading ? (
              <div className="p-8 text-center text-muted-foreground">Loading courts...</div>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Court</TableHead>
                    <TableHead>Price/Hour</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {courts?.map((court) => (
                    <TableRow key={court.id}>
                      <TableCell>
                        <div>
                          <p className="font-medium text-foreground">{court.name}</p>
                          <p className="text-sm text-muted-foreground">{court.description}</p>
                        </div>
                      </TableCell>
                      <TableCell className="font-semibold text-foreground">₱{court.price_per_hour}</TableCell>
                      <TableCell>
                        <Badge variant={court.is_active ? "default" : "secondary"}>
                          {court.is_active ? "Active" : "Inactive"}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right">
                        <Button variant="ghost" size="sm" onClick={() => handleEdit(court)}>
                          <Pencil className="h-4 w-4" />
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            )}
          </CardContent>
        </Card>
      </div>
    </AdminLayout>
  );
};

export default AdminCourts;

import { AdminLayout } from "@/components/admin/AdminLayout";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Link } from "react-router-dom";
import {
  Calendar,
  CreditCard,
  MapPin,
  Trophy,
  QrCode,
  Users,
} from "lucide-react";
import { useAdminBookings, useTodayBookings, useTodayOpenPlay } from "@/hooks/useAdmin";
import { useAllCourts } from "@/hooks/useCourts";
import { format, subDays } from "date-fns";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
} from "recharts";
import { useMemo } from "react";

const statusColors: Record<string, string> = {
  paid: "bg-primary text-primary-foreground",
  pending: "bg-accent text-accent-foreground",
  completed: "bg-muted text-muted-foreground",
  cancelled: "bg-destructive/10 text-destructive",
};

const PIE_COLORS = [
  "hsl(var(--chart-1))",
  "hsl(var(--chart-2))",
  "hsl(var(--chart-3))",
  "hsl(var(--chart-5))",
];

const fmtTime = (t: string) => {
  const [h, m] = t.split(":");
  const d = new Date();
  d.setHours(Number(h), Number(m), 0, 0);
  return format(d, "h:mm a");
};

const AdminDashboard = () => {
  const { data: bookings, isLoading: bookingsLoading } = useAdminBookings();
  const { data: courts, isLoading: courtsLoading } = useAllCourts();
  const { data: todayBookings, isLoading: todayBookingsLoading } = useTodayBookings();
  const { data: todaySessions, isLoading: todaySessionsLoading } = useTodayOpenPlay();

  const isLoading = bookingsLoading || courtsLoading;

  const totalBookings = bookings?.length || 0;
  const totalRevenue =
    bookings
      ?.filter((b: any) => b.status === "paid" || b.status === "completed")
      .reduce((sum, b: any) => sum + Number(b.total_amount || 0), 0) || 0;
  const activeCourts = courts?.filter((c) => c.is_active)?.length || 0;
  const pendingPayments = bookings?.filter((b: any) => b.status === "pending").length || 0;
  const recentBookings = bookings?.slice(0, 5) || [];

  const bookingCheckIns = (todayBookings ?? []).filter((b: any) => !!b.checked_in_at).length;
  const sessionCheckIns = (todaySessions ?? []).reduce((s, x) => s + x.checked_in, 0);
  const expectedToday =
    (todayBookings ?? []).filter((b: any) => b.status === "paid" || b.status === "completed").length +
    (todaySessions ?? []).reduce((s, x) => s + x.registered, 0);

  const revenueData = useMemo(() => {
    if (!bookings) return [];
    const days: Record<string, number> = {};
    for (let i = 6; i >= 0; i--) {
      days[format(subDays(new Date(), i), "MMM d")] = 0;
    }
    bookings.forEach((b: any) => {
      if (b.status === "paid" || b.status === "completed") {
        const day = format(new Date(b.booking_date), "MMM d");
        if (day in days) days[day] += Number(b.total_amount || 0);
      }
    });
    return Object.entries(days).map(([name, revenue]) => ({ name, revenue }));
  }, [bookings]);

  const statusData = useMemo(() => {
    if (!bookings) return [];
    const counts: Record<string, number> = {};
    bookings.forEach((b: any) => {
      counts[b.status] = (counts[b.status] || 0) + 1;
    });
    return Object.entries(counts).map(([name, value]) => ({
      name: name.charAt(0).toUpperCase() + name.slice(1),
      value,
    }));
  }, [bookings]);

  const stats = [
    { title: "Total Bookings", value: totalBookings.toString(), icon: Calendar },
    { title: "Revenue", value: `₱${totalRevenue.toLocaleString()}`, icon: CreditCard },
    { title: "Active Courts", value: activeCourts.toString(), icon: MapPin },
    { title: "Awaiting Payment", value: pendingPayments.toString(), icon: Users },
    {
      title: "Checked In Today",
      value: `${bookingCheckIns + sessionCheckIns}/${expectedToday}`,
      icon: QrCode,
    },
  ];

  return (
    <AdminLayout>
      <div className="p-4 md:p-6 lg:p-8">
        <div className="mb-8 flex flex-wrap items-end justify-between gap-4">
          <div>
            <p className="eyebrow text-muted-foreground">Operations overview</p>
            <h1 className="mt-1 text-2xl font-extrabold tracking-tight text-foreground md:text-3xl">Today at The Pickle Box</h1>
            <p className="text-muted-foreground">
              {format(new Date(), "EEEE, MMMM d, yyyy")} — everything happening today.
            </p>
          </div>
          <div className="flex gap-2">
            <Button asChild size="sm" variant="outline">
              <Link to="/admin/check-in">
                <QrCode className="mr-2 h-4 w-4" /> Open Scanner
              </Link>
            </Button>
            <Button asChild size="sm" variant="outline">
              <Link to="/admin/open-play">
                <Trophy className="mr-2 h-4 w-4" /> Open Play
              </Link>
            </Button>
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-5 gap-4 mb-8">
          {stats.map((stat, index) => (
            <Card key={index} className="hover:shadow-md transition-shadow">
              <CardContent className="p-5">
                <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-primary/10 mb-4">
                  <stat.icon className="h-5 w-5 text-primary" />
                </div>
                {isLoading ? (
                  <Skeleton className="h-8 w-24 mb-1" />
                ) : (
                  <p className="text-2xl font-bold text-foreground mb-1">{stat.value}</p>
                )}
                <p className="text-sm text-muted-foreground">{stat.title}</p>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* Today: Open Play + Bookings */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0">
              <CardTitle className="flex items-center gap-2">
                <Trophy className="h-5 w-5 text-primary" /> Today's Open Play
              </CardTitle>
              <Button asChild variant="ghost" size="sm">
                <Link to="/admin/open-play">Manage</Link>
              </Button>
            </CardHeader>
            <CardContent className="space-y-3">
              {todaySessionsLoading ? (
                [1, 2].map((i) => <Skeleton key={i} className="h-16 w-full" />)
              ) : (todaySessions ?? []).length === 0 ? (
                <p className="text-muted-foreground text-center py-8">No sessions scheduled today</p>
              ) : (
                todaySessions!.map((s) => (
                  <div
                    key={s.id}
                    className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-border p-4"
                  >
                    <div>
                      <p className="font-semibold text-foreground">
                        {s.title || "Open Play"}{" "}
                        <span className="text-muted-foreground font-normal">
                          · {fmtTime(s.start_time)}–{fmtTime(s.end_time)}
                        </span>
                      </p>
                      <p className="text-sm text-muted-foreground">
                        Skill {s.skill} · {s.registered}/{s.max_players} players
                        {s.waitlisted > 0 ? ` · ${s.waitlisted} waitlisted` : ""}
                      </p>
                    </div>
                    <div className="flex items-center gap-2">
                      {s.status === "cancelled" ? (
                        <Badge className="bg-destructive/10 text-destructive">Cancelled</Badge>
                      ) : (
                        <Badge variant="secondary">{s.checked_in} checked in</Badge>
                      )}
                    </div>
                  </div>
                ))
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0">
              <CardTitle className="flex items-center gap-2">
                <Calendar className="h-5 w-5 text-primary" /> Today's Court Bookings
              </CardTitle>
              <Button asChild variant="ghost" size="sm">
                <Link to="/admin/bookings">Manage</Link>
              </Button>
            </CardHeader>
            <CardContent className="space-y-3">
              {todayBookingsLoading ? (
                [1, 2].map((i) => <Skeleton key={i} className="h-16 w-full" />)
              ) : (todayBookings ?? []).length === 0 ? (
                <p className="text-muted-foreground text-center py-8">No bookings for today</p>
              ) : (
                todayBookings!.map((b: any) => (
                  <div
                    key={b.id}
                    className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-border p-4"
                  >
                    <div>
                      <p className="font-semibold text-foreground">
                        {b.full_name}{" "}
                        <span className="text-muted-foreground font-normal">
                          · {b.courts?.name || "Court"}
                        </span>
                      </p>
                      <p className="text-sm text-muted-foreground">
                        {fmtTime(b.start_time)}–{fmtTime(b.end_time)} · ₱{b.total_amount}
                      </p>
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge className={statusColors[b.status] || ""}>
                        {b.status.charAt(0).toUpperCase() + b.status.slice(1)}
                      </Badge>
                      {b.checked_in_at ? (
                        <Badge variant="secondary">
                          In {format(new Date(b.checked_in_at), "h:mm a")}
                        </Badge>
                      ) : (
                        <Badge variant="outline">Not in</Badge>
                      )}
                    </div>
                  </div>
                ))
              )}
            </CardContent>
          </Card>
        </div>

        {/* Charts */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-8">
          <Card className="lg:col-span-2">
            <CardHeader>
              <CardTitle>Revenue (Last 7 Days)</CardTitle>
            </CardHeader>
            <CardContent>
              {isLoading ? (
                <Skeleton className="h-64 w-full" />
              ) : (
                <ResponsiveContainer width="100%" height={280}>
                  <BarChart data={revenueData}>
                    <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                    <XAxis dataKey="name" tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 12 }} />
                    <YAxis tick={{ fill: "hsl(var(--muted-foreground))", fontSize: 12 }} />
                    <Tooltip
                      contentStyle={{
                        background: "hsl(var(--card))",
                        border: "1px solid hsl(var(--border))",
                        borderRadius: "8px",
                        color: "hsl(var(--foreground))",
                      }}
                      formatter={(value: number) => [`₱${value.toLocaleString()}`, "Revenue"]}
                    />
                    <Bar dataKey="revenue" fill="hsl(var(--primary))" radius={[6, 6, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Booking Status</CardTitle>
            </CardHeader>
            <CardContent>
              {isLoading ? (
                <Skeleton className="h-64 w-full" />
              ) : statusData.length === 0 ? (
                <p className="text-muted-foreground text-center py-8">No data</p>
              ) : (
                <ResponsiveContainer width="100%" height={280}>
                  <PieChart>
                    <Pie
                      data={statusData}
                      cx="50%"
                      cy="50%"
                      innerRadius={50}
                      outerRadius={90}
                      paddingAngle={4}
                      dataKey="value"
                      label={({ name, value }) => `${name}: ${value}`}
                    >
                      {statusData.map((_, index) => (
                        <Cell key={index} fill={PIE_COLORS[index % PIE_COLORS.length]} />
                      ))}
                    </Pie>
                    <Tooltip
                      contentStyle={{
                        background: "hsl(var(--card))",
                        border: "1px solid hsl(var(--border))",
                        borderRadius: "8px",
                        color: "hsl(var(--foreground))",
                      }}
                    />
                  </PieChart>
                </ResponsiveContainer>
              )}
            </CardContent>
          </Card>
        </div>

        {/* Recent Bookings */}
        <Card>
          <CardHeader>
            <CardTitle>Recent Bookings</CardTitle>
          </CardHeader>
          <CardContent>
            {isLoading ? (
              <div className="space-y-3">
                {[1, 2, 3].map((i) => <Skeleton key={i} className="h-12 w-full" />)}
              </div>
            ) : recentBookings.length === 0 ? (
              <p className="text-muted-foreground text-center py-8">No bookings yet</p>
            ) : (
              <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Reference</TableHead>
                      <TableHead>Court</TableHead>
                      <TableHead>Date</TableHead>
                      <TableHead>Amount</TableHead>
                      <TableHead>Status</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {recentBookings.map((booking: any) => (
                      <TableRow key={booking.id}>
                        <td className="py-4 px-4 font-mono text-sm text-foreground">{booking.reference_code || "—"}</td>
                        <td className="py-4 px-4 text-sm text-muted-foreground">{booking.courts?.name || "Unknown"}</td>
                        <td className="py-4 px-4 text-sm text-foreground">{format(new Date(booking.booking_date), "MMM d, yyyy")}</td>
                        <td className="py-4 px-4 font-semibold text-foreground">₱{booking.total_amount}</td>
                        <TableCell>
                          <Badge className={statusColors[booking.status] || ""}>
                            {booking.status.charAt(0).toUpperCase() + booking.status.slice(1)}
                          </Badge>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
              </Table>
            )}
          </CardContent>
        </Card>
      </div>
    </AdminLayout>
  );
};

export default AdminDashboard;

import { AdminLayout } from "@/components/admin/AdminLayout";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useAdminPayments } from "@/hooks/useAdmin";
import { format } from "date-fns";

const statusVariant: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
  pending: "outline",
  completed: "default",
  failed: "destructive",
  refunded: "secondary",
};

const AdminPayments = () => {
  const { data: payments, isLoading } = useAdminPayments();

  return (
    <AdminLayout>
      <div className="p-6 lg:p-8">
        <div className="mb-8">
          <h1 className="text-2xl md:text-3xl font-bold text-foreground">Payments</h1>
          <p className="text-muted-foreground">Track all payment transactions</p>
        </div>

        <Card>
          <CardContent className="p-0">
            {isLoading ? (
              <div className="p-8 text-center text-muted-foreground">Loading payments...</div>
            ) : payments?.length === 0 ? (
              <div className="p-8 text-center text-muted-foreground">No payments yet</div>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Booking Ref</TableHead>
                    <TableHead>Court</TableHead>
                    <TableHead>Amount</TableHead>
                    <TableHead>Method</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Paid At</TableHead>
                    <TableHead>Transaction Ref</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {payments?.map((payment: any) => (
                    <TableRow key={payment.id}>
                      <TableCell className="font-mono text-sm text-foreground">
                        {payment.bookings?.reference_code || "—"}
                      </TableCell>
                      <TableCell className="text-foreground">
                        {payment.bookings?.courts?.name || "Unknown"}
                      </TableCell>
                      <TableCell className="font-semibold text-foreground">
                        ₱{payment.amount}
                      </TableCell>
                      <TableCell className="text-muted-foreground capitalize">
                        {payment.payment_method || "—"}
                      </TableCell>
                      <TableCell>
                        <Badge variant={statusVariant[payment.status] || "secondary"}>
                          {payment.status.charAt(0).toUpperCase() + payment.status.slice(1)}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-muted-foreground">
                        {payment.paid_at
                          ? format(new Date(payment.paid_at), "MMM d, yyyy HH:mm")
                          : "—"}
                      </TableCell>
                      <TableCell className="font-mono text-sm text-muted-foreground">
                        {payment.transaction_reference || "—"}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            )}
          </CardContent>
        </Card>
      </div>
    </AdminLayout>
  );
};

export default AdminPayments;

